using Check=std::function<void(bool,const char*)>;
class ActivationBlock {HHOOK hook_=nullptr;public:ActivationBlock(){hook_=SetWindowsHookEx(WH_CBT,[](int code,WPARAM wp,LPARAM lp)->LRESULT{return code==HCBT_ACTIVATE?1:CallNextHookEx(nullptr,code,wp,lp);},nullptr,GetCurrentThreadId());if(!hook_)throw std::runtime_error("Cannot isolate style fixture activation");}~ActivationBlock(){UnhookWindowsHookEx(hook_);}};
sct::core::Image Pixels(){sct::core::Image image;if(!image.Create(320,220))throw std::runtime_error("Cannot allocate style fixture");return image;}
void Codec(Check check,const std::filesystem::path& dir){
    using namespace sct;using namespace sct::services;CString error,data;std::vector<ToolStyle> all;
    for(int i=0;i<=static_cast<int>(core::Tool::CurvedArrow);++i){const auto tool=static_cast<core::Tool>(i);if(!SupportsToolStyle(tool))continue;ToolStyle item;item.name.Format(L"樣式 %d \\\"",i);item.style.tool=tool;item.style.font=L"Microsoft JhengHei UI";item.style.color=RGB(11,22,33);item.style.background=RGB(200,210,220);item.style.width=5;item.style.fontSize=36;item.style.opacity=71;item.style.alpha=190;item.style.bold=true;item.style.italic=true;item.style.textBackground=true;item.style.alignment=4;item.style.mosaicStrength=67;item.style.eraseMode=1;all.push_back(item);}
    std::vector<ToolStyle> loaded;check(EncodeToolStyles(all,data,error)&&DecodeToolStyles(data,loaded,error)&&loaded.size()==all.size(),"bounded style-only codec round trips every supported drawing tool");
    for(size_t i=0;i<loaded.size();++i)check(loaded[i].name==all[i].name&&loaded[i].style.color==RGB(11,22,33)&&loaded[i].style.width==5&&loaded[i].style.fontSize==36&&loaded[i].style.alignment==4&&loaded[i].style.bold&&loaded[i].style.italic&&loaded[i].style.mosaicStrength==67&&loaded[i].style.eraseMode==1&&loaded[i].style.textBackground&&loaded[i].style.rect.right==0&&loaded[i].style.text.IsEmpty()&&!loaded[i].style.asset&&loaded[i].style.points.empty(),"style payload preserves formatting but contains no text, positions or image assets");
    for(auto invalid:{CString(L"2 0"),CString(L"1 33"),data+L" tail",CString(L"1 1 \"x\" 0 \"font\""),data+L"\n"}){const auto old=loaded.size();check(!DecodeToolStyles(invalid,loaded,error)&&loaded.size()==old,"invalid/truncated/versioned style data fails transactionally");}
    auto duplicate=all;duplicate.push_back(all.front());CString output=L"unchanged";check(!EncodeToolStyles(duplicate,output,error)&&output==L"unchanged","duplicate preset names fail without replacing output");auto invalid=all;invalid[0].name=L"bad\nname";check(!EncodeToolStyles(invalid,output,error),"INI-injection control characters in user preset names are rejected");invalid=all;invalid[0].style.width=0;check(!EncodeToolStyles(invalid,output,error),"out-of-range drawing properties are rejected");
    core::Annotation object;object.tool=core::Tool::Text;object.rect={10,20,200,90};object.text=L"document content";object.points={{12,22}};object.asset=std::make_shared<core::Image>(Pixels());const auto asset=object.asset;CopyToolStyle(all.front().style,object);check(object.tool==core::Tool::Text&&object.rect.left==10&&object.text==L"document content"&&object.points[0].x==12&&object.asset==asset&&object.color==RGB(11,22,33),"style application preserves target type, geometry, content and asset identity");
    const auto clean=StyleTemplate(object);check(clean.tool==object.tool&&clean.text.IsEmpty()&&clean.points.empty()&&!clean.asset&&clean.rect.right==0&&clean.color==object.color,"saving a style strips all document-specific state");
    ConfigService config((dir/L"style-config.ini").c_str());Settings original;original.editorHomeConfigured=true;original.editorHome=L"Color,Arrow,More";original.directory=L"D:\\User Folder\\captures";original.toolStyles=data;Settings result;check(config.Save(original,error)&&config.Load(result,error)&&result.toolStyles==data&&result.editorHome==original.editorHome&&result.directory==original.directory,"real portable INI round trip retains Unicode style data and existing ordered settings");
    std::vector<BYTE> before,after;ReadBytes((dir/L"style-config.ini").c_str(),before,error);original.toolStyles=L"invalid";check(!config.Save(original,error)&&ReadBytes((dir/L"style-config.ini").c_str(),after,error)&&after==before,"invalid settings style data cannot overwrite a valid INI");
    check(DecodeToolStyles(L"",loaded,error)&&loaded.empty(),"old INIs without style data retain default drawing behavior");
}
